import re
p='shipclient/retry.py'
s=open(p).read()
s=s.replace("from datetime import datetime\n","""import re
from datetime import datetime, timezone

DEFAULT_PROFILE = (5, 8.0, 30.0)  # attempts, backoff cap, longest Retry-After

# Current retry profiles: service -> (attempts, backoff cap, longest Retry-After)
PROFILES = {
    "catalog": (6, 8.0, 30.0),
    "ledger": (8, 3.0, 60.0),
    "auth": (6, 6.0, 20.0),
    "payments": (3, 1.0, 30.0),
    "ledger-export": (4, 8.0, 10.0),
    "reports": (9, 5.0, 120.0),
    "inventory": (7, 4.0, 90.0),
    "search": (10, 12.0, 45.0),
    "shipping": (8, 3.0, 40.0),
    "media": (5, 8.0, 15.0),
}

_IDEMPOTENT = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
_RETRY_STATUSES = {429, 502, 503, 504}
_MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
           "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
_DAYS = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"}
_HTTP_DATE = re.compile(
    r"([A-Za-z]{3}), (\\d{2}) ([A-Za-z]{3}) (\\d{4}) (\\d{2}):(\\d{2}):(\\d{2}) GMT"
)


def _get(headers, name):
    name = name.lower()
    for k, v in (headers or {}).items():
        if k.lower() == name:
            return v
    return None


def _retry_after(value, now):
    \"\"\"Wait in seconds from a Retry-After value, or None if absent/malformed.\"\"\"
    if value is None:
        return None
    value = value.strip()
    if re.fullmatch(r"[0-9]+", value):
        return float(int(value))
    m = _HTTP_DATE.fullmatch(value)
    if not m or m[1] not in _DAYS or m[3] not in _MONTHS:
        return None
    try:
        when = datetime(int(m[4]), _MONTHS.index(m[3]) + 1, int(m[2]),
                        int(m[5]), int(m[6]), int(m[7]), tzinfo=timezone.utc)
    except ValueError:
        return None
    return max(0.0, (when - now).total_seconds())
""")
s=s.replace("    raise NotImplementedError\n","""    method = method.upper()
    if status is not None and status not in _RETRY_STATUSES:
        return None
    if method not in _IDEMPOTENT:
        key = _get(request_headers, "Idempotency-Key")
        if method not in ("POST", "PATCH") or not (key and key.strip()):
            return None

    service = (_get(request_headers, "X-Service") or "").strip().lower()
    max_attempts, cap, max_wait = PROFILES.get(service, DEFAULT_PROFILE)
    if attempt >= max_attempts:
        return None

    delay = min(0.25 * 2 ** (attempt - 1), cap)
    if status in (429, 503):
        wait = _retry_after(_get(response_headers, "Retry-After"), now)
        if wait is not None:
            if wait > max_wait:
                return None
            delay = max(delay, wait)
    return delay
""")
open(p,'w').write(s)
